package com.finboost.bank.statement.parser.service.document.extraction.nativeextract;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.ArrayList;
import java.util.List;

final class NativePdfGeometry {
    private NativePdfGeometry() {
    }

    @Data
    @NoArgsConstructor
    @AllArgsConstructor
    static class Segment {
        float x1;
        float y1;
        float x2;
        float y2;

        boolean isHorizontal(float tol) {
            return Math.abs(y1 - y2) <= tol && Math.abs(x1 - x2) > tol;
        }

        boolean isVertical(float tol) {
            return Math.abs(x1 - x2) <= tol && Math.abs(y1 - y2) > tol;
        }

        float minX() {
            return Math.min(x1, x2);
        }

        float maxX() {
            return Math.max(x1, x2);
        }

        float minY() {
            return Math.min(y1, y2);
        }

        float maxY() {
            return Math.max(y1, y2);
        }

        float length() {
            float dx = x2 - x1;
            float dy = y2 - y1;
            return (float) Math.sqrt(dx * dx + dy * dy);
        }
    }

    @Data
    @NoArgsConstructor
    @AllArgsConstructor
    static class Rect {
        float x1;
        float y1;
        float x2;
        float y2;

        float width() {
            return Math.max(0f, x2 - x1);
        }

        float height() {
            return Math.max(0f, y2 - y1);
        }

        boolean contains(float x, float y, float tol) {
            return x >= x1 - tol && x <= x2 + tol && y >= y1 - tol && y <= y2 + tol;
        }
    }

    static List<Float> clusterPositions(List<Float> values, float tolerance) {
        List<Float> sorted = new ArrayList<>(values);
        sorted.sort(Float::compare);
        List<Float> clusters = new ArrayList<>();
        if (sorted.isEmpty()) {
            return clusters;
        }
        float sum = sorted.get(0);
        int count = 1;
        float anchor = sorted.get(0);
        for (int i = 1; i < sorted.size(); i++) {
            float v = sorted.get(i);
            if (Math.abs(v - anchor) <= tolerance) {
                sum += v;
                count++;
            } else {
                clusters.add(sum / count);
                sum = v;
                count = 1;
                anchor = v;
            }
        }
        clusters.add(sum / count);
        return clusters;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativeextract;

import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import lombok.Data;
import lombok.extern.slf4j.Slf4j;
import org.apache.pdfbox.Loader;
import org.apache.pdfbox.contentstream.PDFGraphicsStreamEngine;
import org.apache.pdfbox.cos.COSName;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.pdmodel.PDPage;
import org.apache.pdfbox.pdmodel.common.PDRectangle;
import org.apache.pdfbox.pdmodel.graphics.image.PDImage;
import org.apache.pdfbox.text.PDFTextStripper;
import org.apache.pdfbox.text.TextPosition;
import org.springframework.stereotype.Component;

import java.awt.geom.Point2D;
import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedList;
import java.util.List;

/**
 * Offline PDF content extraction: words (inches, top-left) plus stroked path geometry.
 */
@Component
@Slf4j
public class NativePdfContentExtractor {

    private static final float POINTS_PER_INCH = 72.0f;

    @Data
    public static class PageContent {
        private int pageNumber;
        private float widthInches;
        private float heightInches;
        private List<Word> words = new ArrayList<>();
        private List<NativePdfGeometry.Segment> segments = new ArrayList<>();
        private List<NativePdfGeometry.Rect> rectangles = new ArrayList<>();
        private String text;
    }

    public List<PageContent> extract(File pdfFile) throws IOException {
        List<PageContent> pages = new ArrayList<>();
        try (PDDocument document = Loader.loadPDF(pdfFile)) {
            int pageCount = document.getNumberOfPages();
            for (int pageIndex = 0; pageIndex < pageCount; pageIndex++) {
                PDPage pdPage = document.getPage(pageIndex);
                PDRectangle cropBox = pdPage.getCropBox();
                float pageHeightPts = cropBox.getHeight();
                float pageWidthPts = cropBox.getWidth();

                WordExtractor wordExtractor = new WordExtractor(pageHeightPts, pageIndex + 1);
                wordExtractor.setStartPage(pageIndex + 1);
                wordExtractor.setEndPage(pageIndex + 1);
                wordExtractor.setSortByPosition(true);
                String pageText = wordExtractor.getText(document);

                GeometryExtractor geometryExtractor = new GeometryExtractor(pdPage, pageHeightPts);
                try {
                    geometryExtractor.processPage(pdPage);
                } catch (Exception e) {
                    log.debug("Geometry extraction failed on page {}: {}", pageIndex + 1, e.getMessage());
                }

                PageContent pageContent = new PageContent();
                pageContent.setPageNumber(pageIndex + 1);
                pageContent.setWidthInches(pageWidthPts / POINTS_PER_INCH);
                pageContent.setHeightInches(pageHeightPts / POINTS_PER_INCH);
                pageContent.setWords(wordExtractor.getWords());
                pageContent.setSegments(geometryExtractor.getSegments());
                pageContent.setRectangles(geometryExtractor.getRectangles());
                pageContent.setText(pageText);
                pages.add(pageContent);
            }
        }
        return pages;
    }

    private static float toInches(float points) {
        return points / POINTS_PER_INCH;
    }

    private static class WordExtractor extends PDFTextStripper {
        private final float pageHeightPts;
        private final int pageNumber;
        private final List<Word> words = new LinkedList<>();
        private final StringBuilder currentWord = new StringBuilder();
        private float wordMinX;
        private float wordMinY;
        private float wordMaxX;
        private float wordMaxY;
        private boolean building;

        WordExtractor(float pageHeightPts, int pageNumber) throws IOException {
            super();
            this.pageHeightPts = pageHeightPts;
            this.pageNumber = pageNumber;
        }

        List<Word> getWords() {
            flushWord();
            words.sort(Comparator
                    .comparing(Word::getY1)
                    .thenComparing(Word::getX1));
            return words;
        }

        @Override
        protected void processTextPosition(TextPosition text) {
            String unicode = text.getUnicode();
            if (unicode == null || unicode.isEmpty()) {
                return;
            }
            if (Character.isWhitespace(unicode.charAt(0))) {
                flushWord();
                return;
            }

            float x = toInches(text.getXDirAdj());
            float y = toInches(text.getYDirAdj());
            float w = toInches(text.getWidthDirAdj());
            float h = toInches(Math.max(text.getHeightDir(), text.getFontSizeInPt() * 0.8f));

            if (!building) {
                building = true;
                currentWord.setLength(0);
                wordMinX = x;
                wordMinY = y - h;
                wordMaxX = x + w;
                wordMaxY = y;
            } else {
                // new word if large horizontal gap on same line
                if (x - wordMaxX > Math.max(0.08f, (wordMaxX - wordMinX) * 0.35f)
                        || Math.abs(y - wordMaxY) > Math.max(0.06f, h * 0.8f)) {
                    flushWord();
                    building = true;
                    currentWord.setLength(0);
                    wordMinX = x;
                    wordMinY = y - h;
                    wordMaxX = x + w;
                    wordMaxY = y;
                } else {
                    wordMinX = Math.min(wordMinX, x);
                    wordMinY = Math.min(wordMinY, y - h);
                    wordMaxX = Math.max(wordMaxX, x + w);
                    wordMaxY = Math.max(wordMaxY, y);
                }
            }
            currentWord.append(unicode);
        }

        private void flushWord() {
            if (!building || currentWord.length() == 0) {
                building = false;
                return;
            }
            Word word = new Word();
            word.setContent(currentWord.toString());
            word.setPageNumber(pageNumber);
            word.setX1(wordMinX);
            word.setY1(wordMinY);
            word.setX2(wordMaxX);
            word.setY2(wordMinY);
            word.setX3(wordMaxX);
            word.setY3(wordMaxY);
            word.setX4(wordMinX);
            word.setY4(wordMaxY);
            word.setWidth(wordMaxX - wordMinX);
            word.setHeight(wordMaxY - wordMinY);
            words.add(word);
            building = false;
            currentWord.setLength(0);
        }
    }

    private static class GeometryExtractor extends PDFGraphicsStreamEngine {
        private final float pageHeightPts;
        private final List<NativePdfGeometry.Segment> segments = new ArrayList<>();
        private final List<NativePdfGeometry.Rect> rectangles = new ArrayList<>();
        private float currentX;
        private float currentY;
        private float pathStartX;
        private float pathStartY;
        private final List<NativePdfGeometry.Segment> currentPath = new ArrayList<>();

        GeometryExtractor(PDPage page, float pageHeightPts) {
            super(page);
            this.pageHeightPts = pageHeightPts;
        }

        List<NativePdfGeometry.Segment> getSegments() {
            return segments;
        }

        List<NativePdfGeometry.Rect> getRectangles() {
            return rectangles;
        }

        private float tx(float x) {
            return toInches(x);
        }

        private float ty(float y) {
            return toInches(pageHeightPts - y);
        }

        @Override
        public void appendRectangle(Point2D p0, Point2D p1, Point2D p2, Point2D p3) {
            float minX = tx((float) Math.min(Math.min(p0.getX(), p1.getX()), Math.min(p2.getX(), p3.getX())));
            float maxX = tx((float) Math.max(Math.max(p0.getX(), p1.getX()), Math.max(p2.getX(), p3.getX())));
            float minY = ty((float) Math.max(Math.max(p0.getY(), p1.getY()), Math.max(p2.getY(), p3.getY())));
            float maxY = ty((float) Math.min(Math.min(p0.getY(), p1.getY()), Math.min(p2.getY(), p3.getY())));
            if (maxX - minX > 0.02f && maxY - minY > 0.02f) {
                rectangles.add(new NativePdfGeometry.Rect(minX, minY, maxX, maxY));
            }
            segments.add(new NativePdfGeometry.Segment(minX, minY, maxX, minY));
            segments.add(new NativePdfGeometry.Segment(maxX, minY, maxX, maxY));
            segments.add(new NativePdfGeometry.Segment(maxX, maxY, minX, maxY));
            segments.add(new NativePdfGeometry.Segment(minX, maxY, minX, minY));
        }

        @Override
        public void clip(int windingRule) {
        }

        @Override
        public void moveTo(float x, float y) {
            currentX = x;
            currentY = y;
            pathStartX = x;
            pathStartY = y;
        }

        @Override
        public void lineTo(float x, float y) {
            currentPath.add(new NativePdfGeometry.Segment(tx(currentX), ty(currentY), tx(x), ty(y)));
            currentX = x;
            currentY = y;
        }

        @Override
        public void curveTo(float x1, float y1, float x2, float y2, float x3, float y3) {
            currentX = x3;
            currentY = y3;
        }

        @Override
        public Point2D getCurrentPoint() {
            return new Point2D.Float(currentX, currentY);
        }

        @Override
        public void closePath() {
            if (currentX != pathStartX || currentY != pathStartY) {
                currentPath.add(new NativePdfGeometry.Segment(tx(currentX), ty(currentY), tx(pathStartX), ty(pathStartY)));
            }
            currentX = pathStartX;
            currentY = pathStartY;
        }

        @Override
        public void endPath() {
            currentPath.clear();
        }

        @Override
        public void strokePath() {
            commitPath();
        }

        @Override
        public void fillPath(int windingRule) {
            commitPathAsRects();
            currentPath.clear();
        }

        @Override
        public void fillAndStrokePath(int windingRule) {
            commitPath();
        }

        @Override
        public void drawImage(PDImage pdImage) {
        }

        @Override
        public void shadingFill(COSName shadingName) {
        }

        private void commitPath() {
            for (NativePdfGeometry.Segment segment : currentPath) {
                if (segment.length() >= 0.05f) {
                    segments.add(segment);
                }
            }
            currentPath.clear();
        }

        private void commitPathAsRects() {
            if (currentPath.size() >= 3) {
                float minX = Float.MAX_VALUE, minY = Float.MAX_VALUE, maxX = -Float.MAX_VALUE, maxY = -Float.MAX_VALUE;
                for (NativePdfGeometry.Segment s : currentPath) {
                    minX = Math.min(minX, s.minX());
                    minY = Math.min(minY, s.minY());
                    maxX = Math.max(maxX, s.maxX());
                    maxY = Math.max(maxY, s.maxY());
                }
                if (maxX - minX > 0.15f && maxY - minY > 0.08f) {
                    rectangles.add(new NativePdfGeometry.Rect(minX, minY, maxX, maxY));
                }
            }
            commitPath();
        }
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativeextract;

import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.TableCell;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import com.finboost.bank.statement.parser.representation.document.extraction.nativeextract.NativeTablePolicy;

import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

/**
 * Builds structured table rows for the three supported native layout families.
 */
public final class NativeTableBuilders {

    private static final Pattern DATE_PATTERN = Pattern.compile(
            "\\b(\\d{1,2}[-/\\. ]\\d{1,2}[-/\\. ]\\d{2,4}|\\d{1,2}[-/ ][A-Za-z]{3}[-/ ]\\d{2,4}|\\d{1,2}-[A-Za-z]{3}-\\d{2,4})\\b"
    );
    private static final Pattern AMOUNT_PATTERN = Pattern.compile(
            "\\b\\d{1,3}(?:,\\d{2,3})*(?:\\.\\d{1,2})?\\b|\\b\\d+\\.\\d{2}\\b"
    );
    private static final Pattern HEADER_HINT = Pattern.compile(
            "(?i)(txn\\s*date|tran\\s*date|value\\s*date|narration|description|withdrawal|deposit|debit|credit|balance|chq|cheque|ref)"
    );

    private NativeTableBuilders() {
    }

    public static Table build(NativeTablePolicy policy, NativePdfContentExtractor.PageContent page) {
        return switch (policy) {
            case BORDERED_GRID -> buildBorderedGrid(page);
            case BOX_GUIDED -> buildBoxGuided(page);
            case TEXT_ALIGNED_ROW_SELECTED -> buildTextAlignedRowSelected(page);
        };
    }

    public static boolean looksLikeTransactionTable(Table table) {
        if (table == null || table.getCells() == null || table.getCells().size() < 2) {
            return false;
        }
        int dateRows = 0;
        int amountRows = 0;
        for (Map<Integer, TableCell> row : table.getCells().values()) {
            String content = row.values().stream()
                    .sorted(Comparator.comparing(TableCell::getColindex))
                    .map(TableCell::getContent)
                    .collect(Collectors.joining(" "));
            if (HEADER_HINT.matcher(content).find() && !DATE_PATTERN.matcher(content).find()) {
                continue;
            }
            if (DATE_PATTERN.matcher(content).find()) {
                dateRows++;
            }
            if (AMOUNT_PATTERN.matcher(content).find()) {
                amountRows++;
            }
        }
        return dateRows >= 1 && amountRows >= 1 && table.getCells().size() >= 2;
    }

    private static Table buildBorderedGrid(NativePdfContentExtractor.PageContent page) {
        float tol = 0.03f;
        List<Float> hs = new ArrayList<>();
        List<Float> vs = new ArrayList<>();
        for (NativePdfGeometry.Segment s : page.getSegments()) {
            if (s.isHorizontal(tol) && s.length() >= 0.4f) {
                hs.add((s.y1 + s.y2) / 2f);
            } else if (s.isVertical(tol) && s.length() >= 0.15f) {
                vs.add((s.x1 + s.x2) / 2f);
            }
        }
        List<Float> yLines = NativePdfGeometry.clusterPositions(hs, 0.025f);
        List<Float> xLines = NativePdfGeometry.clusterPositions(vs, 0.03f);

        if (xLines.size() < 3 || yLines.size() < 3) {
            return buildTextAlignedRowSelected(page);
        }

        // Keep densest vertical band of horizontal lines (transaction grid body)
        yLines = densestRun(yLines, 0.35f, 4);
        if (yLines.size() < 3) {
            return buildTextAlignedRowSelected(page);
        }

        float tableMinX = xLines.get(0);
        float tableMaxX = xLines.get(xLines.size() - 1);
        float tableMinY = yLines.get(0);
        float tableMaxY = yLines.get(yLines.size() - 1);

        List<Word> inTable = page.getWords().stream()
                .filter(w -> centerX(w) >= tableMinX - 0.05f && centerX(w) <= tableMaxX + 0.05f
                        && centerY(w) >= tableMinY - 0.05f && centerY(w) <= tableMaxY + 0.05f)
                .collect(Collectors.toList());

        Map<Integer, Map<Integer, TableCell>> cells = new LinkedHashMap<>();
        int rows = yLines.size() - 1;
        int cols = xLines.size() - 1;
        for (int r = 0; r < rows; r++) {
            float y1 = yLines.get(r);
            float y2 = yLines.get(r + 1);
            Map<Integer, TableCell> row = new LinkedHashMap<>();
            for (int c = 0; c < cols; c++) {
                float x1 = xLines.get(c);
                float x2 = xLines.get(c + 1);
                TableCell cell = emptyCell(r, c, x1, y1, x2, y2);
                List<Word> cellWords = inTable.stream()
                        .filter(w -> centerX(w) >= x1 - 0.01f && centerX(w) <= x2 + 0.01f
                                && centerY(w) >= y1 - 0.01f && centerY(w) <= y2 + 0.01f)
                        .sorted(Comparator.comparing(Word::getY1).thenComparing(Word::getX1))
                        .collect(Collectors.toList());
                cell.setWords(cellWords);
                row.put(c, cell);
            }
            cells.put(r, row);
        }
        return createTable(page.getPageNumber(), tableMinX, tableMinY, tableMaxX, tableMaxY, rows, cols, cells);
    }

    private static Table buildBoxGuided(NativePdfContentExtractor.PageContent page) {
        List<NativePdfGeometry.Rect> boxes = page.getRectangles().stream()
                .filter(r -> r.width() >= 0.8f && r.height() >= 0.12f && r.height() <= 2.5f)
                .sorted(Comparator.comparing(NativePdfGeometry.Rect::getY1).thenComparing(NativePdfGeometry.Rect::getX1))
                .collect(Collectors.toList());

        if (boxes.size() < 2) {
            // Use long horizontal rules as row guides
            float tol = 0.03f;
            List<Float> hs = page.getSegments().stream()
                    .filter(s -> s.isHorizontal(tol) && s.length() >= 1.0f)
                    .map(s -> (s.y1 + s.y2) / 2f)
                    .collect(Collectors.toList());
            List<Float> yGuides = NativePdfGeometry.clusterPositions(hs, 0.03f);
            if (yGuides.size() >= 3) {
                return buildFromRowGuides(page, yGuides);
            }
            return buildTextAlignedRowSelected(page);
        }

        // Prefer wide boxes that look like table rows
        float medianWidth = median(boxes.stream().map(NativePdfGeometry.Rect::width).collect(Collectors.toList()));
        List<NativePdfGeometry.Rect> rowBoxes = boxes.stream()
                .filter(b -> b.width() >= medianWidth * 0.7f)
                .collect(Collectors.toList());
        if (rowBoxes.size() < 2) {
            return buildTextAlignedRowSelected(page);
        }

        List<Float> yGuides = new ArrayList<>();
        yGuides.add(rowBoxes.get(0).getY1());
        for (NativePdfGeometry.Rect box : rowBoxes) {
            yGuides.add(box.getY2());
        }
        yGuides = NativePdfGeometry.clusterPositions(yGuides, 0.02f);
        return buildFromRowGuides(page, yGuides);
    }

    private static Table buildTextAlignedRowSelected(NativePdfContentExtractor.PageContent page) {
        List<List<Word>> lines = clusterIntoLines(page.getWords(), 0.045f);
        if (lines.isEmpty()) {
            return null;
        }

        int headerIdx = -1;
        for (int i = 0; i < lines.size(); i++) {
            String lineText = join(lines.get(i));
            if (HEADER_HINT.matcher(lineText).find()) {
                long hits = HEADER_HINT.matcher(lineText).results().count();
                if (hits >= 2) {
                    headerIdx = i;
                    break;
                }
            }
        }
        if (headerIdx < 0) {
            // fallback: first line that has a date followed by later amount lines
            for (int i = 0; i < Math.min(lines.size(), 40); i++) {
                if (DATE_PATTERN.matcher(join(lines.get(i))).find()) {
                    headerIdx = Math.max(0, i - 1);
                    break;
                }
            }
        }
        if (headerIdx < 0) {
            return null;
        }

        List<List<Word>> candidateRows = new ArrayList<>();
        candidateRows.add(lines.get(headerIdx));
        for (int i = headerIdx + 1; i < lines.size(); i++) {
            String text = join(lines.get(i));
            if (text.toLowerCase().contains("page ") || text.toLowerCase().contains("statement summary")) {
                break;
            }
            boolean dateLike = DATE_PATTERN.matcher(text).find();
            boolean amountLike = AMOUNT_PATTERN.matcher(text).find();
            boolean continuation = !dateLike && !candidateRows.isEmpty() && lines.get(i).get(0).getX1() > page.getWidthInches() * 0.12f;
            if (dateLike || amountLike || continuation) {
                if (continuation && !candidateRows.isEmpty()) {
                    // merge continuation into previous row
                    candidateRows.get(candidateRows.size() - 1).addAll(lines.get(i));
                } else {
                    candidateRows.add(new ArrayList<>(lines.get(i)));
                }
            } else if (candidateRows.size() > 3 && !dateLike) {
                // stop after leaving transaction block
                if (i > headerIdx + 3) {
                    break;
                }
            }
        }

        if (candidateRows.size() < 2) {
            return null;
        }

        List<Float> colStarts = detectColumns(candidateRows);
        if (colStarts.size() < 2) {
            colStarts = fallbackEqualColumns(candidateRows, 6);
        }

        float minX = (float) candidateRows.stream().flatMap(List::stream).mapToDouble(Word::getX1).min().orElse(0);
        float maxX = (float) candidateRows.stream().flatMap(List::stream).mapToDouble(w -> w.getX1() + w.getWidth()).max().orElse(page.getWidthInches());
        float minY = (float) candidateRows.stream().flatMap(List::stream).mapToDouble(Word::getY1).min().orElse(0);
        float maxY = (float) candidateRows.stream().flatMap(List::stream).mapToDouble(w -> w.getY1() + w.getHeight()).max().orElse(page.getHeightInches());

        List<Float> boundaries = new ArrayList<>(colStarts);
        boundaries.add(maxX + 0.02f);

        Map<Integer, Map<Integer, TableCell>> cells = new LinkedHashMap<>();
        for (int r = 0; r < candidateRows.size(); r++) {
            List<Word> rowWords = candidateRows.get(r);
            Map<Integer, TableCell> row = new LinkedHashMap<>();
            float y1 = (float) rowWords.stream().mapToDouble(Word::getY1).min().orElse(minY);
            float y2 = (float) rowWords.stream().mapToDouble(w -> w.getY1() + w.getHeight()).max().orElse(y1 + 0.15f);
            for (int c = 0; c < boundaries.size() - 1; c++) {
                float x1 = boundaries.get(c);
                float x2 = boundaries.get(c + 1);
                TableCell cell = emptyCell(r, c, x1, y1, x2, y2);
                float left = x1;
                float right = x2;
                List<Word> cellWords = rowWords.stream()
                        .filter(w -> centerX(w) >= left - 0.02f && centerX(w) < right + 0.02f)
                        .sorted(Comparator.comparing(Word::getX1))
                        .collect(Collectors.toList());
                cell.setWords(cellWords);
                if (r == 0) {
                    cell.setHeaderOrFooterCell(true);
                }
                row.put(c, cell);
            }
            cells.put(r, row);
        }
        Table table = createTable(page.getPageNumber(), minX, minY, maxX, maxY, candidateRows.size(), boundaries.size() - 1, cells);
        table.setColumnBoundaries(boundaries);
        return table;
    }

    private static Table buildFromRowGuides(NativePdfContentExtractor.PageContent page, List<Float> yGuides) {
        yGuides = densestRun(yGuides, 0.4f, 3);
        if (yGuides.size() < 3) {
            return buildTextAlignedRowSelected(page);
        }
        float minY = yGuides.get(0);
        float maxY = yGuides.get(yGuides.size() - 1);
        List<Word> words = page.getWords().stream()
                .filter(w -> centerY(w) >= minY - 0.05f && centerY(w) <= maxY + 0.05f)
                .collect(Collectors.toList());
        if (words.isEmpty()) {
            return null;
        }
        List<List<Word>> rows = new ArrayList<>();
        for (int i = 0; i < yGuides.size() - 1; i++) {
            float y1 = yGuides.get(i);
            float y2 = yGuides.get(i + 1);
            List<Word> rowWords = words.stream()
                    .filter(w -> centerY(w) >= y1 - 0.01f && centerY(w) < y2 + 0.01f)
                    .sorted(Comparator.comparing(Word::getX1))
                    .collect(Collectors.toList());
            if (!rowWords.isEmpty()) {
                rows.add(rowWords);
            }
        }
        if (rows.size() < 2) {
            return buildTextAlignedRowSelected(page);
        }
        List<Float> cols = detectColumns(rows);
        if (cols.size() < 2) {
            cols = fallbackEqualColumns(rows, 6);
        }
        float minX = (float) rows.stream().flatMap(List::stream).mapToDouble(Word::getX1).min().orElse(0);
        float maxX = (float) rows.stream().flatMap(List::stream).mapToDouble(w -> w.getX1() + w.getWidth()).max().orElse(page.getWidthInches());
        List<Float> boundaries = new ArrayList<>(cols);
        boundaries.add(maxX + 0.02f);
        Map<Integer, Map<Integer, TableCell>> cells = new LinkedHashMap<>();
        for (int r = 0; r < rows.size(); r++) {
            List<Word> rowWords = rows.get(r);
            float y1 = (float) rowWords.stream().mapToDouble(Word::getY1).min().orElse(minY);
            float y2 = (float) rowWords.stream().mapToDouble(w -> w.getY1() + w.getHeight()).max().orElse(y1 + 0.12f);
            Map<Integer, TableCell> row = new LinkedHashMap<>();
            for (int c = 0; c < boundaries.size() - 1; c++) {
                float x1 = boundaries.get(c);
                float x2 = boundaries.get(c + 1);
                TableCell cell = emptyCell(r, c, x1, y1, x2, y2);
                cell.setWords(rowWords.stream()
                        .filter(w -> centerX(w) >= x1 - 0.02f && centerX(w) < x2 + 0.02f)
                        .collect(Collectors.toList()));
                row.put(c, cell);
            }
            cells.put(r, row);
        }
        return createTable(page.getPageNumber(), minX, minY, maxX, maxY, rows.size(), boundaries.size() - 1, cells);
    }

    private static List<List<Word>> clusterIntoLines(List<Word> words, float yTol) {
        List<Word> sorted = words.stream()
                .sorted(Comparator.comparing(Word::getY1).thenComparing(Word::getX1))
                .collect(Collectors.toList());
        List<List<Word>> lines = new ArrayList<>();
        for (Word word : sorted) {
            if (lines.isEmpty()) {
                List<Word> line = new ArrayList<>();
                line.add(word);
                lines.add(line);
                continue;
            }
            List<Word> last = lines.get(lines.size() - 1);
            float lastY = (float) last.stream().mapToDouble(w -> w.getY1() + w.getHeight() / 2f).average().orElse(word.getY1());
            float wordY = word.getY1() + word.getHeight() / 2f;
            if (Math.abs(wordY - lastY) <= yTol) {
                last.add(word);
            } else {
                List<Word> line = new ArrayList<>();
                line.add(word);
                lines.add(line);
            }
        }
        for (List<Word> line : lines) {
            line.sort(Comparator.comparing(Word::getX1));
        }
        return lines;
    }

    private static List<Float> detectColumns(List<List<Word>> rows) {
        List<Float> starts = new ArrayList<>();
        int sample = Math.min(rows.size(), 12);
        for (int i = 0; i < sample; i++) {
            for (Word w : rows.get(i)) {
                starts.add(w.getX1());
            }
        }
        List<Float> clustered = NativePdfGeometry.clusterPositions(starts, 0.12f);
        // keep clusters that appear often
        List<Float> kept = new ArrayList<>();
        for (Float c : clustered) {
            long count = starts.stream().filter(s -> Math.abs(s - c) <= 0.12f).count();
            if (count >= Math.max(2, sample / 4)) {
                kept.add(c);
            }
        }
        if (kept.size() < 2 && clustered.size() >= 2) {
            return clustered;
        }
        return kept;
    }

    private static List<Float> fallbackEqualColumns(List<List<Word>> rows, int cols) {
        float minX = (float) rows.stream().flatMap(List::stream).mapToDouble(Word::getX1).min().orElse(0);
        float maxX = (float) rows.stream().flatMap(List::stream).mapToDouble(w -> w.getX1() + w.getWidth()).max().orElse(minX + 1);
        List<Float> boundaries = new ArrayList<>();
        for (int i = 0; i < cols; i++) {
            boundaries.add(minX + (maxX - minX) * i / (float) cols);
        }
        return boundaries;
    }

    private static List<Float> densestRun(List<Float> sortedUnique, float maxGap, int minPoints) {
        if (sortedUnique.size() < minPoints) {
            return sortedUnique;
        }
        int bestStart = 0;
        int bestEnd = 0;
        int start = 0;
        for (int i = 1; i < sortedUnique.size(); i++) {
            if (sortedUnique.get(i) - sortedUnique.get(i - 1) > maxGap) {
                if (i - start > bestEnd - bestStart) {
                    bestStart = start;
                    bestEnd = i;
                }
                start = i;
            }
        }
        if (sortedUnique.size() - start > bestEnd - bestStart) {
            bestStart = start;
            bestEnd = sortedUnique.size();
        }
        return new ArrayList<>(sortedUnique.subList(bestStart, bestEnd));
    }

    private static Table createTable(int pageNumber, float x1, float y1, float x2, float y2,
                                     int rows, int cols, Map<Integer, Map<Integer, TableCell>> cells) {
        Table table = new Table();
        table.setPageNumber(pageNumber);
        table.setX1(x1);
        table.setY1(y1);
        table.setX2(x2);
        table.setY2(y1);
        table.setX3(x2);
        table.setY3(y2);
        table.setX4(x1);
        table.setY4(y2);
        table.setTotalRows(rows);
        table.setTotalColumns(cols);
        table.setCells(cells);
        table.setColType(new ArrayList<>());
        table.setTxnColType(new ArrayList<>());
        table.setBankTransactions(false);
        return table;
    }

    private static TableCell emptyCell(int row, int col, float x1, float y1, float x2, float y2) {
        TableCell cell = new TableCell();
        cell.setRowindex(row);
        cell.setColindex(col);
        cell.setRowspan(1);
        cell.setColspan(1);
        cell.setX1(x1);
        cell.setY1(y1);
        cell.setX2(x2);
        cell.setY2(y1);
        cell.setX3(x2);
        cell.setY3(y2);
        cell.setX4(x1);
        cell.setY4(y2);
        cell.setWords(new ArrayList<>());
        return cell;
    }

    private static float centerX(Word w) {
        return (w.getX1() + w.getX2() + w.getX3() + w.getX4()) / 4f;
    }

    private static float centerY(Word w) {
        return (w.getY1() + w.getY2() + w.getY3() + w.getY4()) / 4f;
    }

    private static String join(List<Word> words) {
        return words.stream().map(Word::getContent).collect(Collectors.joining(" "));
    }

    private static float median(List<Float> values) {
        if (values == null || values.isEmpty()) {
            return 0f;
        }
        List<Float> sorted = new ArrayList<>(values);
        sorted.sort(Float::compare);
        return sorted.get(sorted.size() / 2);
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativeextract;

import com.finboost.bank.statement.parser.representation.document.extraction.nativeextract.NativeTablePolicy;
import org.springframework.stereotype.Component;
import org.springframework.util.StringUtils;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

/**
 * Selects a native table policy for bank-format families present in the fixture corpus.
 * Unsupported / unknown banks yield empty so the ML path remains default.
 */
@Component
public class NativeTablePolicySelector {

    private final Map<String, NativeTablePolicy> bankPolicies = new HashMap<>();

    public NativeTablePolicySelector() {
        // Bordered / ruled transaction grids
        register(NativeTablePolicy.BORDERED_GRID,
                "SBI", "PNB", "BOB", "UNION", "INDIAN", "CBI", "FEDERAL",
                "INDIAN_OVERSEAS", "AHMEDNAGAR", "GS_MAHANAGAR_CO_OP_BANK", "TJSB_BANK",
                "SURYODAY_SMALL_FINANCE_BANK_LTD");

        // Box / frame guided layouts
        register(NativeTablePolicy.BOX_GUIDED,
                "AXIS", "YES", "KOTAK", "IDFC", "RBL", "INDUSIND", "BANDHAN", "IDBI");

        // Text-column aligned, row-selected electronic statements
        register(NativeTablePolicy.TEXT_ALIGNED_ROW_SELECTED,
                "HDFC", "ICICI", "STANDARD_CHARTERED", "DEUSTCHE", "CITI");
    }

    private void register(NativeTablePolicy policy, String... banks) {
        for (String bank : banks) {
            bankPolicies.put(normalize(bank), policy);
        }
    }

    public Optional<NativeTablePolicy> select(String bankName) {
        if (!StringUtils.hasText(bankName)) {
            return Optional.empty();
        }
        return Optional.ofNullable(bankPolicies.get(normalize(bankName)));
    }

    public boolean isSupported(String bankName) {
        return select(bankName).isPresent();
    }

    public Set<String> supportedBanks() {
        return Set.copyOf(bankPolicies.keySet());
    }

    private static String normalize(String bankName) {
        return bankName.trim().toUpperCase(Locale.ROOT)
                .replace(' ', '_')
                .replace('-', '_');
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativeextract;

import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionRequest;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionResult;
import com.finboost.bank.statement.parser.representation.document.extraction.Page;
import com.finboost.bank.statement.parser.representation.document.extraction.Table;
import com.finboost.bank.statement.parser.representation.document.extraction.Word;
import com.finboost.bank.statement.parser.representation.document.extraction.nativeextract.ExtractionPath;
import com.finboost.bank.statement.parser.representation.document.extraction.nativeextract.NativeExtractionDiagnostics;
import com.finboost.bank.statement.parser.representation.document.extraction.nativeextract.NativeTablePolicy;
import com.finboost.bank.statement.parser.service.document.extraction.IBankSpecificParsingService;
import com.finboost.bank.statement.parser.service.document.extraction.post.processor.AnalyzeDocuments;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * Offline native transaction-table extraction path.
 */
@Service
@Slf4j
public class NativeDocumentExtractionService {

    private NativePdfContentExtractor nativePdfContentExtractor;
    private NativeTablePolicySelector nativeTablePolicySelector;
    private AnalyzeDocuments analyzeDocuments;
    private IBankSpecificParsingService bankSpecificParsingService;

    @Autowired
    public void setNativePdfContentExtractor(NativePdfContentExtractor nativePdfContentExtractor) {
        this.nativePdfContentExtractor = nativePdfContentExtractor;
    }

    @Autowired
    public void setNativeTablePolicySelector(NativeTablePolicySelector nativeTablePolicySelector) {
        this.nativeTablePolicySelector = nativeTablePolicySelector;
    }

    @Autowired
    public void setAnalyzeDocuments(AnalyzeDocuments analyzeDocuments) {
        this.analyzeDocuments = analyzeDocuments;
    }

    @Autowired
    public void setBankSpecificParsingService(IBankSpecificParsingService bankSpecificParsingService) {
        this.bankSpecificParsingService = bankSpecificParsingService;
    }

    public Optional<DocumentExtractionResult> tryExtract(DocumentExtractionRequest request) {
        NativeExtractionDiagnostics diagnostics = NativeExtractionDiagnostics.builder()
                .nativeAttempted(false)
                .nativeSucceeded(false)
                .build();

        Optional<NativeTablePolicy> policyOpt = nativeTablePolicySelector.select(request.getBankName());
        if (policyOpt.isEmpty()) {
            diagnostics.setNativeFailureReason("UNSUPPORTED_BANK_OR_LAYOUT");
            return Optional.empty();
        }

        NativeTablePolicy policy = policyOpt.get();
        diagnostics.setNativeAttempted(true);
        diagnostics.setNativeTablePolicy(policy);

        try {
            List<NativePdfContentExtractor.PageContent> pageContents =
                    nativePdfContentExtractor.extract(request.getStatementFile());
            if (pageContents == null || pageContents.isEmpty()) {
                diagnostics.setNativeFailureReason("EMPTY_PDF_CONTENT");
                return Optional.empty();
            }

            DocumentExtractionResult result = new DocumentExtractionResult();
            Map<Integer, Page> pages = new HashMap<>();
            int tableCount = 0;
            int rowCount = 0;
            int wordIndex = 1;

            for (NativePdfContentExtractor.PageContent pageContent : pageContents) {
                Page page = new Page();
                page.setPageNumber(pageContent.getPageNumber());
                page.setWidth((double) pageContent.getWidthInches());
                page.setHeight((double) pageContent.getHeightInches());
                page.setWords(pageContent.getWords());
                page.setContent(pageContent.getText());

                Map<Integer, Table> tables = new LinkedHashMap<>();
                Table table = NativeTableBuilders.build(policy, pageContent);
                if (table != null && NativeTableBuilders.looksLikeTransactionTable(table)) {
                    wordIndex = assignWordIndices(table, pageContent.getPageNumber(), wordIndex);
                    tables.put(0, table);
                    tableCount++;
                    rowCount += table.getTotalRows() != null ? table.getTotalRows() : 0;
                }
                page.setTables(tables);
                pages.put(pageContent.getPageNumber(), page);
            }

            result.setPages(pages);
            result.setNoOfPages(pages.size());
            result.setExtractionPath(ExtractionPath.NATIVE);
            result.setNativeTablePolicy(policy);
            diagnostics.setNativeTableCount(tableCount);
            diagnostics.setNativeRowCount(rowCount);

            if (tableCount == 0) {
                diagnostics.setNativeFailureReason("NO_TRANSACTION_TABLE_DETECTED");
                diagnostics.setNativeSucceeded(false);
                result.setNativeExtractionDiagnostics(diagnostics);
                return Optional.empty();
            }

            bankSpecificParsingService.identifyBankSpecificStatementProcess(result, request);
            if (!result.isSkipFurtherProcessing()) {
                DocumentExtractionResult preProcessedByHeader =
                        analyzeDocuments.preProcessForVerificationByHeader(result, 5);
                if (preProcessedByHeader != null && preProcessedByHeader.getPreProcessVerificationResult() != null) {
                    result.setPreProcessVerificationResult(preProcessedByHeader.getPreProcessVerificationResult());
                } else {
                    DocumentExtractionResult preprocessed =
                            analyzeDocuments.preProcessForVerification(result, Math.min(result.getNoOfPages(), 5));
                    if (preprocessed != null && preprocessed.getPreProcessVerificationResult() != null) {
                        result.setPreProcessVerificationResult(preprocessed.getPreProcessVerificationResult());
                    }
                }
                analyzeDocuments.analyzeDocument(result, true, true, true);
            }

            // Re-validate after analysis that at least one transaction table remains usable
            boolean hasTxnTable = result.getPages().values().stream()
                    .filter(p -> p.getTables() != null)
                    .flatMap(p -> p.getTables().values().stream())
                    .anyMatch(t -> t.getIsTransactionTable() || NativeTableBuilders.looksLikeTransactionTable(t));
            if (!hasTxnTable) {
                diagnostics.setNativeFailureReason("POST_ANALYSIS_NO_TRANSACTION_TABLE");
                diagnostics.setNativeSucceeded(false);
                result.setNativeExtractionDiagnostics(diagnostics);
                return Optional.empty();
            }

            diagnostics.setNativeSucceeded(true);
            diagnostics.setExtractionPath(ExtractionPath.NATIVE);
            result.setNativeExtractionDiagnostics(diagnostics);
            result.setExtractionPath(ExtractionPath.NATIVE);
            result.setNativeTablePolicy(policy);
            log.info("Native extraction succeeded for bank={} policy={} tables={} rows={}",
                    request.getBankName(), policy, tableCount, rowCount);
            return Optional.of(result);
        } catch (IOException e) {
            log.warn("Native extraction IO failure for bank={}: {}", request.getBankName(), e.getMessage());
            diagnostics.setNativeFailureReason("IO_ERROR: " + e.getMessage());
            return Optional.empty();
        } catch (Exception e) {
            log.warn("Native extraction failed for bank={}: {}", request.getBankName(), e.getMessage());
            diagnostics.setNativeFailureReason("ERROR: " + e.getMessage());
            return Optional.empty();
        }
    }

    private int assignWordIndices(Table table, int pageNumber, int startIndex) {
        int idx = startIndex;
        if (table.getCells() == null) {
            return idx;
        }
        for (Integer rowIdx : table.getCells().keySet().stream().sorted().toList()) {
            Map<Integer, com.finboost.bank.statement.parser.representation.document.extraction.TableCell> row =
                    table.getCells().get(rowIdx);
            if (row == null) {
                continue;
            }
            for (Integer colIdx : row.keySet().stream().sorted().toList()) {
                var cell = row.get(colIdx);
                if (cell.getWords() == null) {
                    continue;
                }
                for (Word word : cell.getWords()) {
                    word.setPageIndex(pageNumber);
                    word.setWordIndex(idx++);
                }
            }
        }
        return idx;
    }
}

package com.finboost.bank.statement.parser.service.document.extraction.nativeextract;

import com.finboost.bank.statement.parser.representation.bankstatement.BankStatementVO;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionRequest;
import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionResult;
import com.finboost.bank.statement.parser.representation.document.extraction.nativeextract.ExtractionPath;
import com.finboost.bank.statement.parser.representation.document.extraction.nativeextract.NativeExtractionDiagnostics;
import com.finboost.bank.statement.parser.service.document.extraction.DocumentExtractionService;
import com.finboost.bank.statement.parser.service.document.extraction.bankstatement.BankStatementProcessorImpl;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.context.annotation.Primary;
import org.springframework.stereotype.Service;

import java.io.IOException;
import java.util.Optional;

/**
 * Prefers offline native table extraction for supported bank layouts; falls back to remote ML.
 */
@Service
@Primary
@Qualifier("hybridDocumentExtractionService")
@Slf4j
public class HybridDocumentExtractionService implements DocumentExtractionService {

    private NativeDocumentExtractionService nativeDocumentExtractionService;
    private DocumentExtractionService mlDocumentExtractionService;

    @Autowired
    public void setNativeDocumentExtractionService(NativeDocumentExtractionService nativeDocumentExtractionService) {
        this.nativeDocumentExtractionService = nativeDocumentExtractionService;
    }

    @Autowired
    @Qualifier("azureDocumentExtractionServiceImpl")
    public void setMlDocumentExtractionService(DocumentExtractionService mlDocumentExtractionService) {
        this.mlDocumentExtractionService = mlDocumentExtractionService;
    }

    @Override
    public DocumentExtractionResult extractDocument(BankStatementVO bankStatementVO) throws IOException {
        DocumentExtractionRequest request = new DocumentExtractionRequest();
        request.setStatementFile(bankStatementVO.getDecryptedFile());
        request.setBankName(bankStatementVO.getBank());
        try {
            if (bankStatementVO.getBankAccountDetailsVO() != null
                    && bankStatementVO.getBankAccountDetailsVO().getStatementFrom() != null) {
                request.setStatementFromDate(BankStatementProcessorImpl.parseDate(
                        bankStatementVO.getBankAccountDetailsVO().getStatementFrom()));
            }
        } catch (Exception e) {
            log.warn("Failed to parse statement-from-date from date string {}",
                    bankStatementVO.getBankAccountDetailsVO() != null
                            ? bankStatementVO.getBankAccountDetailsVO().getStatementFrom() : null);
        }
        DocumentExtractionResult result = extractDocument(request);
        applyDiagnostics(bankStatementVO, result);
        return result;
    }

    @Override
    public DocumentExtractionResult extractDocument(DocumentExtractionRequest request) throws IOException {
        boolean nativeEligible = nativeDocumentExtractionService != null;
        Optional<DocumentExtractionResult> nativeResult = Optional.empty();
        if (nativeEligible) {
            nativeResult = nativeDocumentExtractionService.tryExtract(request);
        }

        if (nativeResult.isPresent()) {
            DocumentExtractionResult result = nativeResult.get();
            if (result.getExtractionPath() == null) {
                result.setExtractionPath(ExtractionPath.NATIVE);
            }
            if (result.getNativeExtractionDiagnostics() == null) {
                result.setNativeExtractionDiagnostics(NativeExtractionDiagnostics.builder()
                        .extractionPath(ExtractionPath.NATIVE)
                        .nativeTablePolicy(result.getNativeTablePolicy())
                        .nativeAttempted(true)
                        .nativeSucceeded(true)
                        .build());
            }
            return result;
        }

        DocumentExtractionResult mlResult = mlDocumentExtractionService.extractDocument(request);
        boolean attemptedNative = request.getBankName() != null
                && nativeDocumentExtractionService != null;
        ExtractionPath path = attemptedNative && nativeEligible
                ? ExtractionPath.NATIVE_TO_ML_FALLBACK
                : ExtractionPath.ML;
        // Only mark fallback when bank was supported/attempted
        if (mlResult.getNativeExtractionDiagnostics() != null
                && Boolean.TRUE.equals(mlResult.getNativeExtractionDiagnostics().isNativeAttempted())) {
            path = ExtractionPath.NATIVE_TO_ML_FALLBACK;
        } else if (attemptedNative) {
            // tryExtract returns empty for unsupported without attempt flag; detect via selector through diagnostics absence
            // Prefer ML default for unsupported.
            path = ExtractionPath.ML;
        }
        // Improve: if native was attempted (supported bank) but failed, path is fallback
        // NativeDocumentExtractionService only returns empty; we re-check policy
        mlResult.setExtractionPath(path);
        if (mlResult.getNativeExtractionDiagnostics() == null) {
            mlResult.setNativeExtractionDiagnostics(NativeExtractionDiagnostics.builder()
                    .extractionPath(path)
                    .nativeAttempted(false)
                    .nativeSucceeded(false)
                    .build());
        } else {
            mlResult.getNativeExtractionDiagnostics().setExtractionPath(path);
        }
        return mlResult;
    }

    private void applyDiagnostics(BankStatementVO bankStatementVO, DocumentExtractionResult result) {
        if (bankStatementVO == null || result == null) {
            return;
        }
        bankStatementVO.setExtractionPath(result.getExtractionPath());
        bankStatementVO.setNativeTablePolicy(result.getNativeTablePolicy());
        bankStatementVO.setNativeExtractionDiagnostics(result.getNativeExtractionDiagnostics());
    }
}

