    private NativeDocumentExtractionService nativeDocumentExtractionService;
    private DocumentExtractionService mlDocumentExtractionService;

    @Autowired
    public void setNativeDocumentExtractionService(NativeDocumentExtractionService nativeDocumentExtractionService) {
        this.nativeDocumentExtractionService = nativeDocumentExtractionService;
    }

    @Autowired
    @Qualifier("azureDocumentExtractionServiceImpl")
    public void setMlDocumentExtractionService(DocumentExtractionService mlDocumentExtractionService) {
        this.mlDocumentExtractionService = mlDocumentExtractionService;
    }

    @Override
    public DocumentExtractionResult extractDocument(BankStatementVO bankStatementVO) throws IOException {
        DocumentExtractionRequest request = new DocumentExtractionRequest();
        request.setStatementFile(bankStatementVO.getDecryptedFile());
        request.setBankName(bankStatementVO.getBank());
        try {
            if (bankStatementVO.getBankAccountDetailsVO() != null
                    && bankStatementVO.getBankAccountDetailsVO().getStatementFrom() != null) {
                request.setStatementFromDate(BankStatementProcessorImpl.parseDate(
                        bankStatementVO.getBankAccountDetailsVO().getStatementFrom()));
