    public DocumentExtractionResult extractDocument(DocumentExtractionRequest request) throws IOException {
        NativeDocumentExtractionService.NativeAttempt nativeAttempt =
                nativeDocumentExtractionService.attempt(request);

        if (nativeAttempt.isSucceeded() && nativeAttempt.getResult() != null) {
            return nativeAttempt.getResult();
