        DocumentExtractionResult mlResult = mlDocumentExtractionService.extractDocument(request);
        ExtractionPath path = nativeAttempt.isSupported() && nativeAttempt.getDiagnostics().isNativeAttempted()
                ? ExtractionPath.NATIVE_TO_ML_FALLBACK
                : ExtractionPath.ML;

        mlResult.setExtractionPath(path);
        NativeExtractionDiagnostics diagnostics = nativeAttempt.getDiagnostics();
        if (diagnostics == null) {
            diagnostics = NativeExtractionDiagnostics.builder().build();
        }
        diagnostics.setExtractionPath(path);
        diagnostics.setNativeSucceeded(false);
        mlResult.setNativeExtractionDiagnostics(diagnostics);
        if (diagnostics.getNativeTablePolicy() != null) {
            mlResult.setNativeTablePolicy(diagnostics.getNativeTablePolicy());
        }
        log.info("Using {} extraction path for bank={} (nativeSupported={} nativeAttempted={})",
                path, request.getBankName(), nativeAttempt.isSupported(),
                diagnostics.isNativeAttempted());
        return mlResult;
    }

