        Map<Integer, Page> copyPages = this.pages.entrySet().stream()
                .collect(Collectors.toMap(
                        Map.Entry::getKey,
                        entry -> entry.getValue().copy()
                ));


        return new DocumentExtractionResult(
            copyPages,
            this.noOfPages,
            this.accountSummary != null ? this.accountSummary.copy() : null,
            this.isStatementWithReversedOrder,
