    private void applyAccountExtractionPath(AccountVO accountVO, List<BankStatementVO> statements) {
        if (accountVO == null || statements == null || statements.isEmpty()) {
            return;
        }
        ExtractionPath path = ExtractionPath.ML;
        NativeTablePolicy policy = null;
        NativeExtractionDiagnostics diagnostics = null;
        boolean sawNative = false;
        boolean sawMl = false;
        boolean sawFallback = false;
        for (BankStatementVO statement : statements) {
            ExtractionPath statementPath = statement.getExtractionPath();
            if (statementPath == null && statement.getDocumentExtractionResult() != null) {
                statementPath = statement.getDocumentExtractionResult().getExtractionPath();
            }
            if (statementPath == ExtractionPath.NATIVE) {
                sawNative = true;
            } else if (statementPath == ExtractionPath.NATIVE_TO_ML_FALLBACK) {
                sawFallback = true;
            } else if (statementPath == ExtractionPath.ML) {
                sawMl = true;
            }
            if (policy == null) {
                policy = statement.getNativeTablePolicy();
                if (policy == null && statement.getDocumentExtractionResult() != null) {
                    policy = statement.getDocumentExtractionResult().getNativeTablePolicy();
                }
            }
            if (diagnostics == null) {
                diagnostics = statement.getNativeExtractionDiagnostics();
                if (diagnostics == null && statement.getDocumentExtractionResult() != null) {
                    diagnostics = statement.getDocumentExtractionResult().getNativeExtractionDiagnostics();
                }
            }
        }
        if (sawNative && !sawMl && !sawFallback) {
            path = ExtractionPath.NATIVE;
        } else if (sawFallback || (sawNative && sawMl)) {
            path = ExtractionPath.NATIVE_TO_ML_FALLBACK;
        } else {
            path = ExtractionPath.ML;
        }
        accountVO.setExtractionPath(path);
        accountVO.setNativeTablePolicy(policy);
        accountVO.setNativeExtractionDiagnostics(diagnostics);
    }

    /**
     * Removes duplicate transactions from the list while handling description variations.
     * The method:
     * 1. Groups transactions by date, type, amount, and balance
     * 2. Within each group, compares cleaned descriptions to identify duplicates
     * 3. Preserves the original order of transactions
